// C++20 Opposite-End Two Pointers Template
#include <span>
#include <optional>
#include <utility>

std::optional<std::pair<int, int>> twoSumSorted(std::span<const int> nums, int target) {
    if (nums.size() < 2) return std::nullopt;
    int left = 0;
    int right = static_cast<int>(nums.size()) - 1;

    while (left < right) {
        int current_sum = nums[left] + nums[right];
        if (current_sum == target) {
            return std::make_pair(left, right);
        } else if (current_sum < target) {
            ++left;
        } else {
            --right;
        }
    }
    return std::nullopt;
}

// C++20 Dynamic Sliding Window Template
#include <string_view>
#include <unordered_map>
#include <algorithm>

int lengthOfLongestSubstringKDistinct(std::string_view s, int k) {
    if (k <= 0 || s.empty()) return 0;
    std::unordered_map<char, int> freq;
    int max_len = 0;
    int left = 0;

    for (int right = 0; right < static_cast<int>(s.size()); ++right) {
        freq[s[right]]++;
        while (static_cast<int>(freq.size()) > k) {
            char left_char = s[left++];
            if (--freq[left_char] == 0) {
                freq.erase(left_char);
            }
        }
        max_len = std::max(max_len, right - left + 1);
    }
    return max_len;
}

// C++20 Fast & Slow Pointers Template
struct ListNode {
    int val;
    ListNode* next;
};

bool hasCycle(ListNode* head) {
    if (!head || !head->next) return false;
    ListNode* slow = head;
    ListNode* fast = head;

    while (fast && fast->next) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) {
            return true;
        }
    }
    return false;
}

// C++20 Monotonic Decreasing Stack Template (Next Greater Element)
#include <vector>
#include <stack>

std::vector<int> nextGreaterElements(const std::vector<int>& nums) {
    int n = nums.size();
    std::vector<int> result(n, -1);
    std::stack<int> st; // Stores indices

    for (int i = 0; i < n; ++i) {
        while (!st.empty() && nums[i] > nums[st.top()]) {
            int prev_idx = st.top();
            st.pop();
            result[prev_idx] = nums[i];
        }
        st.push(i);
    }
    return result;
}

// C++20 Backtracking Template (Combinations)
#include <vector>

void backtrack(int start, int n, int k, std::vector<int>& current, std::vector<std::vector<int>>& result) {
    if (static_cast<int>(current.size()) == k) {
        result.push_back(current);
        return;
    }
    for (int i = start; i <= n; ++i) {
        current.push_back(i);        // Choose
        backtrack(i + 1, n, k, current, result); // Explore
        current.pop_back();          // Un-choose (Backtrack)
    }
}

// C++20 Binary Search Template
#include <span>
#include <optional>

template <class T>
std::optional<std::size_t> lower_bound(std::span<const T> a, T target) {
    std::size_t lo = 0, hi = a.size();
    while (lo < hi) {
        const std::size_t mid = lo + (hi - lo) / 2;
        if (a[mid] < target) { lo = mid + 1; } else { hi = mid; }
    }
    return lo == a.size() ? std::nullopt : std::optional<std::size_t>{lo};
}

// C++20 Frequency Count Template
#include <unordered_map>
#include <vector>
#include <optional>

std::optional<std::size_t> find_pair(std::span<const int> a, int target) {
    std::unordered_map<int, std::size_t> seen;
    for (std::size_t i = 0; i < a.size(); ++i) {
        const int need = target - a[i];
        if (auto it = seen.find(need); it != seen.end()) {
            return it->second;
        }
        seen.emplace(a[i], i);
    }
    return std::nullopt;
}

// C++20 Min-Heap Template
#include <queue>
#include <vector>

class MinHeap {
    std::vector<int> a_;
    void sift_up(std::size_t i) {
        while (i > 0) {
            const std::size_t p = (i - 1) / 2;
            if (a_[p] <= a_[i]) break;
            std::swap(a_[p], a_[i]); i = p;
        }
    }
    void sift_down(std::size_t i) {
        const std::size_t n = a_.size();
        for (;;) {
            const std::size_t l = 2 * i + 1, r = l + 1;
            std::size_t m = i;
            if (l < n && a_[l] < a_[m]) m = l;
            if (r < n && a_[r] < a_[m]) m = r;
            if (m == i) break;
            std::swap(a_[m], a_[i]); i = m;
        }
    }
public:
    void push(int v) { a_.push_back(v); sift_up(a_.size() - 1); }
    int top() const { return a_.front(); }
    int pop() {
        const int out = a_.front();
        a_.front() = a_.back(); a_.pop_back();
        if (!a_.empty()) sift_down(0);
        return out;
    }
    bool empty() const { return a_.empty(); }
};

// C++20 Trie Template
#include <array>
#include <string>
#include <optional>

class Trie {
    struct Node {
        std::array<int, 26> child{};
        bool terminal = false;
        Node() { child.fill(-1); }
    };
    std::vector<Node> nodes_{Node()};
public:
    void insert(const std::string& s) {
        int cur = 0;
        for (char ch : s) {
            const int c = ch - 'a';
            if (nodes_[cur].child[c] == -1) {
                nodes_[cur].child[c] = static_cast<int>(nodes_.size());
                nodes_.emplace_back();
            }
            cur = nodes_[cur].child[c];
        }
        nodes_[cur].terminal = true;
    }
    bool contains(const std::string& s) const {
        int cur = 0;
        for (char ch : s) {
            const int nxt = nodes_[cur].child[ch - 'a'];
            if (nxt == -1) return false;
            cur = nxt;
        }
        return nodes_[cur].terminal;
    }
    bool starts_with(const std::string& p) const {
        int cur = 0;
        for (char ch : p) {
            const int nxt = nodes_[cur].child[ch - 'a'];
            if (nxt == -1) return false;
            cur = nxt;
        }
        return true;
    }
};

// C++20 Traversal Selection Template
#include <vector>
#include <queue>
#include <functional>

std::vector<int> bfs(const std::vector<std::vector<int>>& adj, int src) {
    std::vector<bool> seen(adj.size(), false);
    std::queue<int> q;
    std::vector<int> order;
    seen[src] = true; q.push(src);
    while (!q.empty()) {
        const int u = q.front(); q.pop();
        order.push_back(u);
        for (int v : adj[u]) if (!seen[v]) { seen[v] = true; q.push(v); }
    }
    return order;
}

// C++20 DP Template
#include <vector>
#include <algorithm>

// 0/1 knapsack: maximise value with weight <= w.
int knapsack(std::span<const int> weights, std::span<const int> values, int w) {
    std::vector<int> dp(static_cast<std::size_t>(w) + 1, 0);
    for (std::size_t i = 0; i < weights.size(); ++i) {
        for (int c = w; c >= weights[i]; --c) {   // descending: each item once
            dp[static_cast<std::size_t>(c)] = std::max(
                dp[static_cast<std::size_t>(c)],
                dp[static_cast<std::size_t>(c - weights[i])] + values[i]);
        }
    }
    return dp[static_cast<std::size_t>(w)];
}

// C++20 Backtracking Template
#include <vector>
#include <functional>

void generate(std::vector<int>& cur, int target,
              const std::function<void(std::vector<int>&)>& undo,
              const std::function<void()>& recurse) {
    // 1. base case  2. prune  3. try, recurse, undo
    for (int v = 0; v <= target; ++v) {
        if (v < 0 || v > target) continue;   // monotone: safe to skip
        cur.push_back(v);
        recurse();
        cur.pop_back();   // undo exactly, after the recursion
    }
}

// C++20 Sort Selection Template
#include <algorithm>
#include <numeric>
#include <span>

// Stable merge sort over a scratch buffer allocated once.
void merge_sort(std::span<int> a, std::span<int> scratch) {
    if (a.size() <= 1) return;
    const std::size_t mid = a.size() / 2;
    merge_sort(a.first(mid), scratch.first(mid));
    merge_sort(a.subspan(mid), scratch.subspan(mid));
    std::merge(a.begin(), a.begin() + static_cast<long>(mid),
              a.begin() + static_cast<long>(mid), a.end(), scratch.begin());
    std::copy(scratch.begin(), scratch.begin() + static_cast<long>(a.size()), a.begin());
}

// C++20 Disjoint-Set Union Template
#include <numeric>
#include <vector>

class DisjointSet {
    std::vector<int> parent_, rank_;
public:
    explicit DisjointSet(int n) : parent_(n), rank_(n, 0) { std::iota(parent_.begin(), parent_.end(), 0); }
    int find(int x) {
        while (parent_[x] != x) { parent_[x] = parent_[parent_[x]]; x = parent_[x]; }
        return x;
    }
    bool unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return false;            // already connected
        if (rank_[a] < rank_[b]) std::swap(a, b);
        parent_[b] = a;
        if (rank_[a] == rank_[b]) ++rank_[a];
        return true;
    }
};

// C++20 Bit Manipulation Template (C++20 gives std::popcount / std::countr_zero)
#include <bit>
#include <cstdint>
#include <optional>

std::optional<std::uint32_t> odd_element(std::span<const std::uint32_t> a) {
    std::uint32_t acc = 0;
    for (auto v : a) acc ^= v;
    return acc;
}

int count_bits(std::uint32_t v) { return std::popcount(v); }
int lowest_set_bit_index(std::uint32_t v) {
    return v == 0 ? -1 : std::countr_zero(v);
}
